import { getDatabase } from "@/lib/db";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

async function checkRequest(request: Request) {
  const id = crypto.randomUUID();
  const timestamp = new Date().toISOString();
  const database = await getDatabase();

  await database.execute({
    sql: "INSERT INTO request_checks (id, method, timestamp) VALUES (?, ?, ?)",
    args: [id, request.method, timestamp],
  });

  return Response.json({
    method: request.method,
    id,
    timestamp,
  });
}

export const GET = checkRequest;
export const POST = checkRequest;
export const PUT = checkRequest;
export const PATCH = checkRequest;
export const DELETE = checkRequest;
export const OPTIONS = checkRequest;
export const HEAD = checkRequest;
